CREATE DATABASE IF NOT EXISTS eventease CHARACTER SET utf8mb4;
USE eventease;
CREATE TABLE admins(id INT AUTO_INCREMENT PRIMARY KEY,name VARCHAR(100) NOT NULL,email VARCHAR(150) NOT NULL UNIQUE,password VARCHAR(255) NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE events(id INT AUTO_INCREMENT PRIMARY KEY,event_name VARCHAR(150) NOT NULL,description TEXT,category VARCHAR(50) NOT NULL,event_date DATE NOT NULL,start_time TIME NOT NULL,end_time TIME NOT NULL,venue VARCHAR(150) NOT NULL,organizer VARCHAR(100) NOT NULL,capacity INT NOT NULL CHECK(capacity>0),registration_start DATE NOT NULL,registration_end DATE NOT NULL,image VARCHAR(255) DEFAULT NULL,status ENUM('Draft','Published','Registration Open','Registration Closed','Completed') DEFAULT 'Draft',created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,INDEX(category),INDEX(event_date));
CREATE TABLE participants(id INT AUTO_INCREMENT PRIMARY KEY,full_name VARCHAR(100) NOT NULL,email VARCHAR(150) NOT NULL UNIQUE,mobile VARCHAR(15) NOT NULL,college VARCHAR(150) NOT NULL,department VARCHAR(100) NOT NULL,semester VARCHAR(10) NOT NULL,enrollment_no VARCHAR(50) NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE registrations(id INT AUTO_INCREMENT PRIMARY KEY,event_id INT NOT NULL,participant_id INT NOT NULL,registration_id VARCHAR(30) NOT NULL UNIQUE,entry_code VARCHAR(12) NOT NULL UNIQUE,registered_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,status VARCHAR(20) DEFAULT 'Confirmed',UNIQUE(event_id,participant_id),FOREIGN KEY(event_id) REFERENCES events(id) ON DELETE CASCADE,FOREIGN KEY(participant_id) REFERENCES participants(id) ON DELETE CASCADE);
CREATE TABLE checkins(id INT AUTO_INCREMENT PRIMARY KEY,event_id INT NOT NULL,participant_id INT NOT NULL,registration_id INT NOT NULL UNIQUE,checkin_time TIMESTAMP DEFAULT CURRENT_TIMESTAMP,status VARCHAR(20) DEFAULT 'Checked In',FOREIGN KEY(registration_id) REFERENCES registrations(id) ON DELETE CASCADE,FOREIGN KEY(event_id) REFERENCES events(id) ON DELETE CASCADE);
CREATE TABLE activity_log(id INT AUTO_INCREMENT PRIMARY KEY,type VARCHAR(30),message VARCHAR(255),created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
